from pathlib import Path
root=Path(__file__).resolve().parents[1]
p=root/'src/voice-main.cjs';s=p.read_text(encoding='utf-8')
a="function dispatch(request,turn=session.turn){privacy?.assertAllowed();if(live!==session)return Promise.reject(new Error('Conversation stopped.'));let job=session.jobs.get(turn);if(!job){status({phase:'liveInterrupt',id:session.id});job=Promise.resolve().then(()=>runWindowsTask(request,{signal:session.controller.signal,source:'gemini_live',utteranceId:session.uid+':'+turn}));session.jobs.set(turn,job);job.catch(()=>{});}return job;}"
b="const taskTurns=runWindowsTask?require('./live-task-turns.cjs').createLiveTaskTurns({signal:session.controller.signal,run:(request,turn)=>{privacy?.assertAllowed();if(live!==session)throw new Error('Conversation stopped.');status({phase:'liveInterrupt',id:session.id});return runWindowsTask(request,{signal:session.controller.signal,source:'gemini_live',utteranceId:session.uid+':'+turn});}}):null;"
assert a in s;s=s.replace(a,b).replace('message:await dispatch(request)','message:await taskTurns.propose(request)').replace('session.jobs.has(session.turn)','taskTurns?.hasProposal()')
s=s.replace("text:action?'Working on your request.':session.text", "text:action?'Working on your request.':''")
a="if(action&&raw&&!content.interrupted){dispatch(raw,turn).then(answer=>{finish(answer);if(s.speak&&live===session)speak(answer);},error=>finish('Task incomplete: '+error.message));}\n        else{for(const data of audio)if(!content.interrupted)status({phase:'liveAudio',id:session.id,audio:data,rate:24000,volume:s.companion?.volume??1});finish(text);}"
b="const taskResult=taskTurns?.finish(raw,{interrupted:!!content.interrupted});if(taskResult){taskResult.then(answer=>{finish(answer);if(s.speak&&live===session&&session.turn===turn+1)speak(answer);},error=>finish('Task incomplete: '+error.message));}\n        else{for(const data of audio)if(raw&&!content.interrupted)status({phase:'liveAudio',id:session.id,audio:data,rate:24000,volume:s.companion?.volume??1});finish(raw?text:'Transcript unavailable. No desktop action was taken.');}"
assert a in s;s=s.replace(a,b);p.write_text(s,encoding='utf-8')
